template <class T>
struct traits {
    static constexpr bool is_integral_type = std::is_integral_v<T>;  // Compile-time check using type traits
    // Implementation notes: The compiler instantiates this template for each T, using SFINAE (Substitution Failure Is Not An Error) for overload resolution. If T is not valid, the instantiation fails silently, allowing metaprogramming techniques like static_assert or enable_if to control code generation without runtime checks. Memory layout: This struct has no runtime memory footprint if all members are constexpr, as the compiler optimizes them away.

code_example:
#include <iostream>
#include <type_traits>
template <class T>
struct my_traits {
    static constexpr bool is_pointer = std::is_pointer_v<T>;  // Compile-time evaluation
};
template <class Iter>
void process(Iter it) {
    if constexpr (my_traits<Iter>::is_pointer) {  // Compile-time if for metaprogramming
        std::cout << "Processing pointer iterator" << std::endl;
    } else {
        std::cout << "Processing non-pointer iterator" << std::endl;
    }
}
int main() {
    int* ptr = nullptr;  // Pointer type
    process(ptr);  // Instantiates for int*
    int value = 42;  // Non-pointer type
    process(&value);  // Instantiates for int* again, but could be different in other contexts
    return 0;
}
